const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-141, -1, -139, 1]); // Equatorial Pacific, around 140W, 1 degree N/S of equator
  const scale = 4638.3; // SeaWiFS nominal resolution for L3 is ~4km

  const date_aug98_start = '1998-08-01';
  const date_aug98_end = '1998-08-31';

  const date_dec99_start = '1999-12-01';
  const date_dec99_end = '1999-12-31';

  const chlCollection = ee.ImageCollection('NASA/OCEANDATA/SeaWiFS/L3/CHL');

  // Function to process a single month
  const getMonthlyChl = (startDate, endDate, name) => {
    const collection = chlCollection.filterDate(startDate, endDate)
      .filterBounds(region);

    const size = collection.size().getInfo();
    if (size === 0) {
      console.log(`No images found for ${name} (${startDate} to ${endDate}).`);
      return { value: null, count: 0, size: 0 };
    }

    // Mosaic and take the mean of the 'chlor_a' band
    const monthlyImage = collection.mean();

    // Calculate mean chlorophyll and pixel count
    const stats = monthlyImage.select('chlor_a').reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    });

    const meanChl = stats.get('chlor_a').getInfo();
    const pixelCount = stats.get('chlor_a_count').getInfo();

    return { value: meanChl, count: pixelCount, size: size };
  };

  // 2. Data Acquisition & Check for August 1998
  const stats_aug98 = getMonthlyChl(date_aug98_start, date_aug98_end, "August 1998");
  console.log(`August 1998: Images: ${stats_aug98.size}, Pixels: ${stats_aug98.count}, Chl: ${stats_aug98.value ? stats_aug98.value.toFixed(2) : 'N/A'}`);

  if (stats_aug98.size === 0) {
    console.log("C1");
    return;
  }
  if (stats_aug98.count === 0) {
    console.log("C2");
    return;
  }
  if (stats_aug98.value === null || isNaN(stats_aug98.value)) {
    console.log("C3");
    return;
  }

  // 3. Data Acquisition & Check for December 1999
  const stats_dec99 = getMonthlyChl(date_dec99_start, date_dec99_end, "December 1999");
  console.log(`December 1999: Images: ${stats_dec99.size}, Pixels: ${stats_dec99.count}, Chl: ${stats_dec99.value ? stats_dec99.value.toFixed(2) : 'N/A'}`);

  if (stats_dec99.size === 0) {
    console.log("C1");
    return;
  }
  if (stats_dec99.count === 0) {
    console.log("C2");
    return;
  }
  if (stats_dec99.value === null || isNaN(stats_dec99.value)) {
    console.log("C3");
    return;
  }

  // 4. Comparison and Final Answer
  const chl_aug98 = stats_aug98.value;
  const chl_dec99 = stats_dec99.value;

  if (chl_dec99 < chl_aug98) {
    console.log("A"); // Yes, chlorophyll concentration decreased
  } else {
    console.log("B"); // No, chlorophyll concentration did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
